export const FIELD_MODULES = FIELD_UPGRADES;
export const FIELD_LIMITS = { modules: 18, upgrades: 36, items: 36 };
export function cleanFieldIds(values, catalogue, limit = 36) {
  const result = [],
    counts = {};
  for (const id of (Array.isArray(values) ? values : []).slice(0, 144)) {
    if (
      typeof id !== 'string' ||
      !Object.hasOwn(catalogue, id) ||
      (counts[id] || 0) >= catalogue[id].maxStacks
    )
      continue;
    result.push(id);
    counts[id] = (counts[id] || 0) + 1;
    if (result.length >= limit) break;
  }
  return result;
}
export const cleanFieldUpgrades = (values) =>
  cleanFieldIds(values, FIELD_UPGRADES, FIELD_LIMITS.upgrades);
export const cleanFieldItems = (values) => cleanFieldIds(values, FIELD_ITEMS, FIELD_LIMITS.items);
